C++Python <pre><code>std::vector&lt;float&gt; safe_softmax(const std::vector&lt;float&gt;&amp; x) {
    if (x.empty()) return {};

    std::vector&lt;float&gt; result(x.size());

    // ​第一步​：​找到​输入​向量​中​的​最大值​ x_max
    float max_val = *std::max_element(x.begin(), x.end());

    // ​第二步​：​计算​ e^(x_i - x_max) ​并​求和​
    float sum_exp = 0.0f;
    for (size_t i = 0; i &lt; x.size(); ++i) {
        result[i] = std::exp(x[i] - max_val); // ​指数​上限​被​限制​为​ e^0 = 1.0，​绝不​溢出​
        sum_exp += result[i];
    }

    // ​第三步​：​归一化​
    for (size_t i = 0; i &lt; x.size(); ++i) {
        result[i] /= sum_exp;
    }

    return result;
}
