# 2. ​安全​的​ Softmax（Safe Numerically Stable Softmax）
# ==========================================
def safe_softmax(x):
    arr = np.array(x, dtype=np.float32)
    if arr.size == 0:
        return np.array([])

    # ​第一步​：​找到​输入​向量​中​的​最大值​ x_max
    max_val = np.max(arr)

    # ​第二步​：​计算​ e^(x_i - x_max) ​并​求和​（​利用​ NumPy ​的​广播​机制​）
    exp_x = np.exp(arr - max_val)  # ​指数​上限​被​限制​为​ e^0 = 1.0，​绝不​溢出​
    sum_exp = np.sum(exp_x)

    # ​第三步​：​归一化​
    return exp_x / sum_exp
