C++Python <pre><code>// ========================================================
// 1. Online Softmax (Single-Pass ​动态​修正​求​ Max ​和​ Sum)
// ========================================================
std::vector&lt;float&gt; online_softmax(const std::vector&lt;float&gt;&amp; x) {
    if (x.empty()) return {};

    size_t n = x.size();
    std::vector&lt;float&gt; result(n);

    // m ​代表​当前​的​局部​最大值​ (m_i)
    // l ​代表​当前​的​局部​指数​和​ (d_i)
    float m = -std::numeric_limits&lt;float&gt;::infinity();
    float l = 0.0f;

    // ----------------------------------------------------
    // Pass 1: ​单次​遍历​，​动态​求​出​全局​ m ​和​全局​ d，​同时​计算​未​完全​归一化​的​分子​
    // ----------------------------------------------------
    for (size_t i = 0; i &lt; n; ++i) {
        float m_prev = m;

        // 1. ​更新​最大值​
        m = std::max(m_prev, x[i]);

        // 2. ​计算​旧​指数​和​的​缩放​因子​ e^(m_prev - m)
        // ​注意​：​当​ m_prev ​为​ -Inf ​时​（​第一次​迭代​），​缩放​因子​设​为​ 0
        float scale = std::exp(m_prev - m);

        // 3. ​动态​修正​旧​的​ sum_exp，​并​加上​新元素​的​ e^(x[i] - m)
        l = l * scale + std::exp(x[i] - m);
    }

    // ​此时​ m ​为​全局​最大值​，l ​为​基于​全局​最大值​的​精确​指数​和​ sum(e^(x_i - m))

    // ----------------------------------------------------
    // Pass 2: ​归一化​计算​最终​概率​ (​仅​用于​输出​结果​)
    // ----------------------------------------------------
    for (size_t i = 0; i &lt; n; ++i) {
        result[i] = std::exp(x[i] - m) / l;
    }

    return result;
}
</code></pre> <pre><code># ========================================================
# 1. Online Softmax (​单次​遍历​ ​动态​修正​求​ Max ​和​ Sum)
# ========================================================
def online_softmax(x):
    arr = np.array(x, dtype=float)
    if arr.size == 0:
        return np.array([])

    n = arr.size
    result = np.zeros(n)

    m = -np.inf
    l = 0.0

    # ​模拟​单次​遍历​逐个​元素​更新​（​对应​ C++ online_softmax）
    for i in range(n):
        val = arr[i]
        m_prev = m

        # 1. ​更新​最大值​
        m = max(m_prev, val)

        # 2. ​计算​旧​指数​和​的​缩放​因子​ e^(m_prev - m)
        # ​第一次​迭代​时​ m_prev ​为​ -inf，np.exp(-inf) ​为​ 0.0
        scale = np.exp(m_prev - m)

        # 3. ​动态​修正​旧​的​ sum_exp，​并​加上​新元素​
        l = l * scale + np.exp(val - m)

    # ​归一化​计算​最终​概率​
    for i in range(n):
        result[i] = np.exp(arr[i] - m) / l

    return result
