C++Python <pre><code>std::vector&lt;float&gt; online_softmax_normed_output(
    const std::vector&lt;float&gt;&amp; logits,
    const std::vector&lt;std::vector&lt;float&gt;&gt;&amp; values) 
{
    size_t n = logits.size();
    if (n == 0 || values.empty()) return {};
    size_t vec_dim = values[0].size();

    float m = -std::numeric_limits&lt;float&gt;::infinity(); // ​局部​ Max
    float l = 0.0f;                                     // ​局部​ Sum Exp

    // O ​始终保持​为​“​已​归一化​”​的​向量​，​初始​全​ 0
    std::vector&lt;float&gt; O(vec_dim, 0.0f);

    for (size_t i = 0; i &lt; n; ++i) {
        float x_i = logits[i];
        const auto&amp; v_i = values[i];

        float m_prev = m;
        m = std::max(m_prev, x_i);

        // 1. ​计算​缩放​因子​与​新元素​的​未​归一化​权重​
        float scale = std::exp(m_prev - m);
        float w_i = std::exp(x_i - m);

        // 2. ​更新​新​的​分母​ d_new
        float l_prev = l;
        l = l_prev * scale + w_i;

        // 3. ​动态​递推​更新​已经​归一化​的​ O ​向量​
        // alpha ​为​旧​ O ​向量​的​保留​权重​，beta ​为​新​ v_i ​向量​的​混合​权重​
        float alpha = (l_prev * scale) / l;  // ​当​ i=0 (d_prev=0) ​时​，alpha ​恰好​为​ 0
        float beta = w_i / l;

        for (size_t j = 0; j &lt; vec_dim; ++j) {
            // ​直接​在线​更新​已​归一化​的​结果​，​无需​在​循环​外​除以​ l
            O[j] = alpha * O[j] + beta * v_i[j];
        }
    }

    // ​循环​结束​时​，O ​已经​是​完全​归一化​后​的​最终​结果​！
    return O;
}
</code></pre> <pre><code># ========================================================
# 1. ​在线​归一化​输出​（​对应​ C++ online_softmax_normed_output）
# ========================================================
def online_softmax_normed_output(logits, values):
    logits = np.array(logits, dtype=float)
    values = np.array(values, dtype=float)

    n = logits.size
    if n == 0 or values.size == 0:
        return np.array([])

    vec_dim = values.shape[1]

    m = -np.inf  # ​局部​ Max
    l = 0.0      # ​局部​ Sum Exp

    # O ​始终保持​为​“​已​归一化​”​的​向量​，​初始​全​ 0
    O = np.zeros(vec_dim, dtype=float)

    for i in range(n):
        x_i = logits[i]
        v_i = values[i]

        m_prev = m
        m = max(m_prev, x_i)

        # 1. ​计算​缩放​因子​与​新元素​的​未​归一化​权重​
        scale = np.exp(m_prev - m)
        w_i = np.exp(x_i - m)

        # 2. ​更新​新​的​分母​ l
        l_prev = l
        l = l_prev * scale + w_i

        # 3. ​动态​递推​更新​已经​归一化​的​ O ​向量​
        alpha = (l_prev * scale) / l if l != 0 else 0.0
        beta = w_i / l if l != 0 else 0.0

        O = alpha * O + beta * v_i

    return O
