C++Python <pre><code>std::vector&lt;float&gt; online_softmax_unnormed_output(
    const std::vector&lt;float&gt;&amp; logits,
    const std::vector&lt;std::vector&lt;float&gt;&gt;&amp; values) 
{
    size_t n = logits.size();
    if (n == 0 || values.empty()) return {};
    size_t vec_dim = values[0].size();

    // 1. ​初始化​统计​量​与​未​归一化​的​累加​向量​ O_unnorm
    float m = -std::numeric_limits&lt;float&gt;::infinity(); // ​局部​ Max
    float l = 0.0f;                                     // ​局部​ Sum Exp
    std::vector&lt;float&gt; O_unnorm(vec_dim, 0.0f);        // ​未​归一化​的​输出​向量​分子​

    // ---------------------------------------------------------------------
    // Single-Pass ​遍历​：​一次​循环​同步​完成​ Max ​更新​、Exp ​修正​与​向量​累加​
    // ---------------------------------------------------------------------
    for (size_t i = 0; i &lt; n; ++i) {
        float x_i = logits[i];
        const auto&amp; v_i = values[i];

        float m_prev = m;
        m = std::max(m_prev, x_i);

        // ​计算​修正​缩放​因子​
        float scale = std::exp(m_prev - m);
        float w_i = std::exp(x_i - m);

        // A. ​动态​更新​分母​ d
        l = l * scale + w_i;

        // B. ​动态​更新​分子​向量​ O_unnorm:
        //    ​旧​的​分子​向量​按​ scale ​缩放​，​并​叠加​当前​新​向量​ w_i * v_i
        for (size_t j = 0; j &lt; vec_dim; ++j) {
            O_unnorm[j] = O_unnorm[j] * scale + w_i * v_i[j];
        }
    }

    // ---------------------------------------------------------------------
    // ​最终​归一化​：​将​累加​向量​分子​除以​全局​分母​ d
    // ---------------------------------------------------------------------
    std::vector&lt;float&gt; O(vec_dim, 0.0f);
    for (size_t j = 0; j &lt; vec_dim; ++j) {
        O[j] = O_unnorm[j] / l;
    }

    return O;
}
