# ========================================================
def online_softmax_unnormed_output(logits, values):
    logits = np.array(logits, dtype=float)
    values = np.array(values, dtype=float)

    n = logits.size
    if n == 0 or values.size == 0:
        return np.array([])

    vec_dim = values.shape[1]

    m = -np.inf  # ​局部​ Max
    l = 0.0      # ​局部​ Sum Exp
    O_unnorm = np.zeros(vec_dim, dtype=float)  # ​未​归一化​的​输出​向量​分子​

    for i in range(n):
        x_i = logits[i]
        v_i = values[i]

        m_prev = m
        m = max(m_prev, x_i)

        # ​计算​修正​缩放​因子​
        scale = np.exp(m_prev - m)
        w_i = np.exp(x_i - m)

        # A. ​动态​更新​分母​ l
        l = l * scale + w_i

        # B. ​动态​更新​分子​向量​ O_unnorm
        O_unnorm = O_unnorm * scale + w_i * v_i

    # ​最终​归一化​：​将​累加​向量​分子​除以​全局​分母​ l
    O = O_unnorm / l if l != 0 else O_unnorm
    return O
